-- Customers: the people who sell, collect and keep the books read them; an owner, an accountant
-- or a sales manager adds and changes them. A customer row carries a CNIC and a credit limit, so
-- the warehouse and payroll roles do not read it.
CREATE POLICY customers_select ON public.customers FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor', 'sales_manager', 'salesperson', 'recovery_officer')
  );
--> statement-breakpoint
CREATE POLICY customers_insert ON public.customers FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager')
    AND created_by = (SELECT app.current_user_id())
    AND updated_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint
CREATE POLICY customers_update ON public.customers FOR UPDATE TO app_runtime
  USING (tenant_id = (SELECT app.tenant_id()) AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager'))
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND (SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager')
    AND updated_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint

