-- Contacts and addresses follow the party they belong to: whoever reads or changes a customer
-- reads or changes its contacts, and the same for a supplier.
CREATE POLICY contacts_select ON public.contacts FOR SELECT TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND CASE WHEN customer_id IS NOT NULL
          THEN (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor', 'sales_manager', 'salesperson', 'recovery_officer')
          ELSE (SELECT app.tenant_role()) IN ('owner', 'accountant', 'auditor', 'warehouse_manager')
        END
  );
--> statement-breakpoint
CREATE POLICY contacts_insert ON public.contacts FOR INSERT TO app_runtime
  WITH CHECK (
    tenant_id = (SELECT app.tenant_id())
    AND CASE WHEN customer_id IS NOT NULL
          THEN (SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager')
          ELSE (SELECT app.tenant_role()) IN ('owner', 'accountant')
        END
    AND created_by = (SELECT app.current_user_id())
    AND updated_by = (SELECT app.current_user_id())
  );
--> statement-breakpoint
CREATE POLICY contacts_update ON public.contacts FOR UPDATE TO app_runtime
  USING (
    tenant_id = (SELECT app.tenant_id())
    AND CASE WHEN customer_id IS NOT NULL
          THEN (SELECT app.tenant_role()) IN ('owner', 'accountant', 'sales_manager')
          ELSE (SELECT app.tenant_role()) IN ('owner', 'accountant')
        END
  )
  WITH CHECK (tenant_id = (SELECT app.tenant_id()) AND updated_by = (SELECT app.current_user_id()));
--> statement-breakpoint
